```latex
\section{Construction Framework}
\subsection{Base Graph $G_B$}
\paragraph{Vertices.} The vertices of the base graph are $[1, x] \times [1, y]$, where $x, y$ are positive integers that are inputs to the construction.
We imagine these vertices as a subset of $\zz^2$, i.e., embedded as points in the Euclidean plane.

\paragraph{The Strongly Convex Set $W$.}
\begin{definition}[Strongly Convex Set]
A set of vectors $W$ is strongly convex if the equation $\vec{v}_0 = \lambda_1\vec{v}_1 + \cdots + \lambda_k\vec{v}_k$ has no nontrivial solutions with all $\vec{v}_i \in W$, $k$ any positive integer, and $\lambda_i$ (possibly negative) scalars with $\sum_i|\lambda_i| \leq 1$. The trivial solutions are when $\vec{v}_0 = \vec{v}_1 = \cdots = \vec{v}_k$.
\end{definition}

We will write our strongly convex set as $W(r, \psi)$ to mean that (1) the $x$-coordinate of all vectors is between $r/2$ and $r$, and (2) the angle between any vector and the horizontal is in the range $[0, \psi]$ radians.

\paragraph{Critical Pairs.}

Let $r$ be an integer parameter of $G_B$ and $W(r, \psi)$ be our chosen strongly convex set. 
Let $S = [1, r/2] \times [1, y/2]$, and let $T = [x - r, x] \times [1, y]$.
The critical pairs $P$ are a subset of $S \times T$.
Specifically: for each $s \in S$ and each $\vec{v} \in W(r, \psi)$, let $t = s + k\vec{v}$ where $k$ is the largest positive integer such that $t \in V$, and include $(s, t) \in P$.

\paragraph{Edges and Canonical Paths.}

Each critical pair $(s, t) \in P$ is generated using a vector $\vec{v} \in W(r, \psi)$; we call this the \emph{canonical vector} of $(s, t)$.
We define the \emph{canonical $(s, t)$-path $\pi_B^{s, t}$} the $(s \leadsto t)$-path containing exactly the edges of the form $(s + i\vec{v}, s+ (i+1)\vec{v})$ for integers $0 \le i < k$. 
The edges of the graph are exactly those contained in any canonical path.

\subsection{Composing the Final Graph $G$}
\paragraph{Inner Graph and Outer Graph.} We instantiate two different copies of our base graph, which we will call the \textit{inner graph} $G_I = (V_I, E_I)$ and the \textit{outer graph} $G_O = (V_O, E_O)$.
We will use subscripts $I$ and $O$ to indicate the inputs used to create $G_I, G_O$ respectively.
That is: the inner graph has dimensions $x_I, y_I$, strongly convex set $W_I(r_I, \psi_I)$, critical pairs $P_I$, and canonical paths $\pi_I^{s, t}$.
The outer graph parameters are the same with subscript $O$.

\paragraph{Inner Graph Replacement Step.} 
The next step in the construction of $G$ is to replace each  vertex in $G_O$ with a copy of the inner graph $G_I$.  
For each vertex $u$ in $G_O$ replaced with a copy $G_I^{u}$ of $G_I$, we must reconnect every edge originally incident to $u$ in $G_O$ to some vertex in $G_I^u$. Recall that the critical pair set $P_I$ is a subset of $S_I \times T_I$. We will regard the source vertices $S_I$ to be the \textit{input ports} of $G_I^u$ and the sink vertices $T_I$ to be the \textit{output ports} of $G_I^u$.

To perform this attachment, we define a bijection $\phi: W_O \mapsto P_I$ from the vectors in the outer graph's strongly convex set to the critical pairs in $P_I$.
If $\vec{v} \in W_O$ and $\phi(\vec{v}) = (s, t)$, we plug in the incoming edge $(u - \vec{v}, u)$ into input port $s$ in $G_I^u$, and we plug in the outgoing edge of form $(u, u + \vec{v})$ originally in $G_O$ into output port $t$ in $G_I^u$.
We repeat this process for all copies of $G_I$ and all vectors $\vec{v} \in W_O$. Let $G'$ be the graph resulting from this process.

\paragraph{Edge Subdivision Step.} Let $z$ be a new parameter of the construction. To obtain our final graph $G$, we subdivide every edge of $G'$ corresponding to an original edge in outer graph $G_O$ into a path of length $z = |V_I|\cdot |P_I|^{-1}$, by adding  new nodes along the edge. 
We refer to the paths in $G$ replacing edges from $G_O$ as  \textit{subdivided paths}.

\paragraph{Critical pairs.} We define the critical pairs $P$ associated to the final graph $G$ as follows:
\begin{itemize}
    \item For each $(s_O, t_O) \in P_O$, let $G_I^{s_O}$ and $G_I^{t_O}$ be the inner graph copies in $G$ corresponding to vertices $s_O$ and $t_O$ in $G_O$.
    Let $\vec{v}_O$ be the canonical vector corresponding to critical pair $(s_O, t_O) \in P_O$, and let $\phi(\vec{v}_O) = (s_I, t_I) \in P_I$.
    \item We then add a critical pair to $P$ from the vertex $s_I$ in $G_I^{s_O}$ paired with the vertex $s_I$ in $G_I^{t_O}$. Denote these vertices in $G$ as $s$ and $t$, respectively.
    \item The associated canonical $(s, t)$-path $\pi^{s, t}$ through the final graph $G$ is the one obtained by starting with $\pi_O^{s_O, t_O}$ and replacing each edge with the corresponding subdivided path in $G$ and each node $u$ with the canonical path $\pi_I^{s_I, t_I}$ in the graph $G_I^u$, except that we replace the final node $t_O$ with the single node $s_I$ in $G_I^{t_O}$.We define vector $\vec{v}_O \in W_O$ to be the canonical vector of $G$ associated with $\pi^{s, t}$. 
\end{itemize}

\section{Analysis Framework}
\label{sec:analysis_1}

Fix a critical pair of vertices $(s, t) \in P$ in our final graph $G$. 
Let $\pi^*$ denote the canonical path corresponding to critical pair $(s, t)$ in $G$, and let $\pi$ be any alternate $s \leadsto t$ path.

\begin{definition}[Moveset $\mathcal{M}$] Let $\pi$ be a $(u, v)$-path in $G$ from some input port $u \in S_I$ in some inner graph copy $G_I^{(1)}$ to some input port $v \in S_I$ in some inner graph copy $G_I^{(2)}$. If no internal vertex of $\pi$ is an input port, then we call $\pi$ a move. We define the following categories of moves in $G$.
\begin{itemize}
    \item \textbf{\textsc{Forward Move}.} Path $\pi$ is a forward move if it travels from $u$ to some output port $w \in T_I$ in $G_I^{(1)}$ and then takes a subdivided path $e$ from $w$ to reach input port $v$ in $G_I^{(2)}$.
    \item \textbf{\textsc{Backward Move}.} Path $\pi$ is a backward move if it takes some subdivided path $e$ incident to $u$ to reach some output port $w \in T_I$ in $G_I^{(2)}$ and then travels to input port $v$ in  $G_I^{(2)}$.
    \item \textbf{\textsc{Zigzag Move}.} Path $\pi$ is a zigzag move if it takes some subdivided path $e_1$ incident to $u$ to reach some output port $w_1 \in T_I$ in some inner graph copy $G_I^{(3)}$, then travels to some output port $w_2 \in T_I$ in $G_I^{(3)}$, and then takes a subdivided path $e_2$ incident to $w_2$ to reach vertex $v$ in $G_I^{(2)}$.
    \item \textbf{\textsc{Stationary Move}.} Path  $\pi$ is a stationary move if $G_I^{(1)} = G_I^{(2)}$, i.e. if $u$ and $v$ are input ports in the same inner graph copy. 
\end{itemize}
We define the moveset $\mathcal{M}$ to be the collection of these categories of moves, namely
\[\mathcal{M} = \{\textsc{Forward, Backward, Zigzag, Stationary}\}.\]
\end{definition}

\begin{proposition}
Every simple $(s, t)$-path $\pi$ can be decomposed into a sequence of pairwise internally vertex-disjoint moves from the moveset.
\end{proposition}

Fix a simple $(s, t)$-path $\pi$, and let $m_1, m_2, \dots, m_k$ be its move decomposition, where $m_i$ is a move from an input port $s_i$ in inner graph copy $G_I^{(i)}$ to an  input port $s_{i+1}$ in inner graph copy $G_I^{(i+1)}$, and $s_1 = s$ and $s_{k+1} = t$. If an inner graph copy $G_I^{(i)}$ replaces a vertex $v \in V_O$ in $G$, then we will let $\texttt{coord}(G_I^{(i)})$ be the vector in $\mathbb{Z}^2$ with the coordinates of $v$. 

\begin{definition}[Move vector]
The move vector $\vec{m_i}$ corresponding to  move $m_i$ is defined as
$$\vec{m_i} = \coord\left(G_I^{(i+1)} \right) - \coord\left(G_I^{(i)} \right).$$
\end{definition}

Let  $\vec{v}^* \in W_O$ be the canonical vector corresponding to canonical $(s, t)$-path $\pi^*$. 

\begin{definition}[Move distance]
The move distance $d_i$ corresponding to move vector $\vec{m}_i$ is defined as $d_i = \proj_{\vec{v}^*}\vec{m}_i$, that is, the (possibly negative) scalar projection of the vector $\vec{m}_i$ onto $\vec{v}^*$ in the standard Euclidean inner product.
\end{definition}

 \begin{definition}[Unit length of $\pi^*$]
 We define the unit length $L_{\pi^*}$ of $\pi^*$  as $L_{\pi^*} := \frac{|\pi^*|}{\|t - s\|}$. 
 \end{definition}

\begin{definition}[Move length difference]
$\Delta(m_i) = |m_i| - L_{\pi^*}  d_i$
\end{definition}

\begin{definition}[Amortized move difference]
$\widehat{\Delta}(m_i) := \Delta(m_i) - \left(\Phi\left(s_{i+1}\right) - \Phi\left(s_i\right)\right)$ 
\end{definition}

\section{Specifying the Construction \label{sec:specifying}}
In the following notation, we will let $n_I = |V_I|$ and $n_O = |V_O|$.
We also use a parameter $c > 0$.

\subsection{Specifying the Inner Graph}
We set $r_I = c^{102}$.
We then define $W_I$ to be the set of $c$ vectors
$$\left\{\left(r_I - c + i, \sum_{j=i}^c j\right) \mid i \in [1, c] \right\}.$$

\subsection{Specifying the Outer Graph}

\begin{lemma}[Outer Graph Strongly Convex Set]
\label{lem:outer_graph_SCS}
For sufficiently large parameters $c, r_O$ we may construct a strongly convex set $W_O = W_O(r_O, \psi_O)$ containing $\Theta(r_O^{2/3}c^{-5})$ integer vectors in $\mathbb{Z}^2$ with the following properties:
\begin{enumerate}
    \item For all $\vec{v} \in W_O$, $r_O - r_O^{-1/3} \leq \|\vec{v}\| \leq r_O$. 
    \item For all $\vec{u}, \vec{v} \in W_O$, $\proj_{\vec{v}}\vec{u}  \leq \|\vec{v}\|$.
    \item For all $\vec{v} \in W_O$, the angle between vector $\vec{v}$ and the horizontal is at most $\psi_O = \pi/4$  radians.
    \item For all $\vec{u}, \vec{v} \in W_O$, the angle between $\vec{u}$ and $\vec{v}$ is at most $\psi_1 = c^{-5}$ radians.
    \item $W_O$ can be partitioned into $c$ stripes $\mathcal{S}_1, \mathcal{S}_2, \dots, \mathcal{S}_c$ with the following properties:
    \begin{enumerate}
        \item $|\mathcal{S}_i| = \beta =  \Theta(r_O^{2/3}c^{-6})$ for all $i \in [1, c]$. 
        \item For $\vec{u} \in \mathcal{S}_i$ and $\vec{v} \in \mathcal{S}_j$ where $i \neq j$, the angle between $\vec{u}$ and $\vec{v}$ is at least $\psi_2 = c^{-10}$ radians. 
    \end{enumerate}
\end{enumerate}
\end{lemma}

\begin{lemma}[Outer Graph Properties]
\label{lemma:outer_graph}
Outer graph $G_O = (V_O, E_O)$ has the following properties:
\begin{enumerate}
    \item $|V_O| = n_O$
    \item $|E_O| = \Theta(c^{-5}\cdot r_O^{2/3}\cdot n_O)$
    \item $|P_O| = \Theta(c^{-5} \cdot r_O^{5/3} \cdot n_O^{1/2})$
    \item The canonical paths $\pi_O^{s, t}$ for $(s, t) \in P_O$ are pairwise edge-disjoint.
    \item The canonical path $\pi_O^{s, t}$ is the unique shortest $(s, t)$-path in $G_O$ for all $(s, t) \in P_O$. 
\end{enumerate}
\end{lemma}

\subsection{Specifying the Final Graph \label{sec:specifyingfinal}}

\begin{lemma}[Properties of Final Graph $G$]
\label{lem:final_graph_2}
Graph $G = (V, E)$ has the following properties:
\begin{enumerate}
    \item $|V| = \Theta( r_O^{4/3} \cdot c^{-116} \cdot n_O )$
    \item $|E| = \sum_{(s, t) \in P} |\pi^{s, t}| =  \Theta(c \cdot |V|)$ 
    \item $|P| = \Theta(r_O^{5/3} \cdot c^{-5} \cdot n_O^{1/2})$
    \item The subdivided paths of $G$ are of length $z = |V_I| |P_I|^{-1} = \Theta(r_O^{2/3} c^{-111})$.
    \item The set of canonical paths $\{\pi^{s, t} \mid (s, t) \in P \}$ form a partition of $E$. 
\end{enumerate}
\end{lemma}

\section{Completing the Analysis}
\label{sec:analysis_2}
As in Section \ref{sec:analysis_1}, fix a critical pair of vertices $(s, t) \in P$ in our final graph $G$ with canonical path $\pi^*$ and canonical vector $\vec{v}^*$. We will compare $\pi^*$ to an arbitrary simple $(s, t)$-path $\pi$, with move decomposition $m_1, m_2, \dots, m_k$. As before, move $m_i$ is a move from an input port $s_i$ in inner graph copy $G_I^{(i)}$ to an input port $s_{i+1}$ in inner graph copy $G_I^{(i+1)}$, and $s_1 = s$ and $s_{k+1} = t$. 

Now to analyze the forward moves in $\mathcal{M}$, we find it useful to partition the set \textsc{Forward} into sets \textsc{Forward-S} and \textsc{Forward-D}, depending on the vector in $W_O$ corresponding to the subdivided path taken in the move. Let $m$ be a move in \textsc{Forward}. Then $m$ is in \textsc{Forward-S}  if move vector $\vec{m} \in W_O$  belongs to the \textit{same} stripe as vector $\vec{v}^*$ in $W_O$. Otherwise, move vector $\vec{m}$ belongs to a \textit{different} stripe than $\vec{v}^*$ and $m$ is in \textsc{Forward-D}.

\subsection{Lower Bounding the Amortized Move Difference $\widehat{\Delta}$}

 Let $(s^*, t^*) \in P_I$ be the inner graph critical pair whose canonical path $\pi_I^{s^*, t^*}$ is a subpath of $\pi^*$ in $G_I$, and let $s^* := (s_1^*, s_2^*)$ and $t^* := (t_1^*, t_2^*)$. 
 Note that by construction of $G$,  $(s^*, t^*) = \phi(\vec{v}^*)$. 
Additionally, let  $\vec{v}_I^* := (v_{I, 1}^*, v_{I, 2}^*) = (r_I - c + i^*, \sum_{j=i^*}^c j) \in W_I$ be the canonical inner graph vector corresponding to  critical pair $(s^*, t^*) \in P_I$, where $i^* \in [1, c]$. Then for $s_i = (s_{i, 1}, s_{i, 2}) \in S_I$ we define our inner graph potential function $\Phi$  to be 
\[\Phi(s_i) = \frac{s_{i, 2} \cdot ( i^*)^{-1} + s_{i, 1}}{r_I - c + i^*}\]

\begin{lemma}
Let $m_i$ be a move in \normalfont \textsc{Stationary}.
\textit{Then}
$\widehat{\Delta}(m_i) \geq 0 $.
\label{lem:stat_move}
\end{lemma}

\begin{lemma}
Let $m_i$ be a move in $\normalfont \textsc{Forward-S}$. Then $\widehat{\Delta}(m_i) \geq 0$. \label{lem:forward_s_moves}
\end{lemma}
